// Real Pyodide run in Node, not a physical browser/device benchmark.
// Input is a LOCAL synthetic reference generated by Python (no user recording).
import {readFile,writeFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
import {performance} from 'node:perf_hooks';
const root=resolve(import.meta.dirname,'..'),directory=resolve(root,'.local/compute-runtime');
const fixture=JSON.parse(await readFile(resolve(root,'.local/sobriety-wasm-reference.json'),'utf8'));
const {loadPyodide}=await import(pathToFileURL(resolve(directory,'pyodide.mjs')).href);
const begun=performance.now(),py=await loadPyodide({indexURL:directory+'/',stdout:()=>{},stderr:()=>{}});
await py.loadPackage(['numpy','scipy','pydantic']);
py.unpackArchive(Uint8Array.from(await readFile(resolve(directory,'numerical.zip'))),'zip',{extractDir:'/home/pyodide'});
py.runPython('import sys,json,numpy as np,scipy\nsys.path.insert(0,"/home/pyodide")\nfrom lab.compute import compute\nfrom lab.graph import render\nfrom lab.schema import Patch');
const report={environment:'Node + Pyodide, pas un appareil physique',initialization_ms:performance.now()-begun,tolerances:{wave_max:1e-7,wave_rms:1e-7,objective_abs:1e-8},cases:{}};
for(const [name,reference] of Object.entries(fixture)){
 py.globals.set('fixture_json',JSON.stringify(reference));
 const start=performance.now();
 const result=JSON.parse(py.runPython(`f=json.loads(fixture_json)
r=compute('compact',f['request'],np.array(f['input']),f['fs'])
y=render(Patch.model_validate(r['patch']))
e=y-np.array(f['output'])
json.dumps({'wave_max':float(np.max(abs(e))),'wave_rms':float(np.sqrt(np.mean(e*e))),'objective_abs':abs(r['final']-f['error']),'types':[n['type'] for n in r['patch']['nodes']],'blocks':r['final_blocks'],'generators':r['final_generators'],'algorithm_version':r['compute_metrics']['algorithm_version']})`));
 result.compute_ms=performance.now()-start;
 result.passed=result.wave_max<=1e-7&&result.wave_rms<=1e-7&&result.objective_abs<=1e-8&&JSON.stringify(result.types)===JSON.stringify(reference.types);
 report.cases[name]=result;
}
report.versions=JSON.parse(py.runPython('json.dumps({"python":sys.version.split()[0],"numpy":np.__version__,"scipy":scipy.__version__})'));
await writeFile(resolve(root,'docs/sobriety-wasm-validation.json'),JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify(report,null,2));
if(Object.values(report.cases).some(c=>!c.passed))process.exitCode=1;
